css:
/* --- 基础容器与字体 --- */
.print-format.print-format-preview {
    padding: 5mm !important;
}

.print-format {
    font-family: "HarmonyOS Sans SC", "HarmonyOSHans-Regular", "HarmonyOSHans-fallback", "PingFangSC-Regular", "Microsoft YaHei", "Arial", "Helvetica", sans-serif !important;
    font-size: 14px;
    font-style: normal;
    font-weight: 420;
    line-height: 21px;
    letter-spacing: 0.14px;
    color: #171717;
    background: white;
    padding: 0mm !important;
    margin-left: 0mm !important;
    margin-right: 0mm !important;
    margin-top: 0mm !important;
    margin-bottom: 0mm !important;
}

/* --- 表头 (Letterhead) 优化 --- */
.letter-head {
    margin-top: 0 !important; /* PDF 渲染时为页头留出顶部空间 */
    margin-bottom: 0 !important; /* 压缩表头与正文间距 */
    padding: 0 !important;
}


/* 针对 wkhtmltopdf 的图片修复 */
.letter-head img {
    max-width: 100% !important;
    height: auto !important;
    width: auto !important;
    display: inline-block !important;
}

/* --- 正文标题区域 --- */
.print-format-body {
    padding: 2mm 4mm !important; /* 移除多余内边距 */
}

.print-format-body h2 {
    font-size: 20px;
    font-weight: 700;
    margin: 0;
    letter-spacing: 1px;
}

.title {
    color: #74808b !important; /* 统一标签颜色 */
    font-size: 12px;
    font-weight: normal;
}

/* --- 订单包装器样式 --- */
.order-wrapper {
    font-family: "Inter", sans-serif;
    color: var(--black-overlay-700, #000);
    font-size: 12px;
    line-height: 1.4;
}

/* --- 打印格式包装器通用样式 --- */
.print-format-wrapper {
    font-family: "HarmonyOS Sans SC", "HarmonyOSHans-Regular", "PingFangSC-Regular", "Microsoft YaHei", "Arial", "Helvetica", sans-serif;
    font-size: 13px;
    line-height: 1.6;
    color: #171717;
    margin: 0;
    padding: 0;
    position: relative;
}

.print-format-wrapper .header-title {
    margin-top: 0;
    margin-bottom: 20px;
}

.print-format-wrapper .header-title h2 {
    font-size: 20px;
    font-weight: 700;
    color: #171717;
    letter-spacing: 1px;
    margin: 0;
}

/* --- 间距工具类 --- */
.print-format-wrapper .mb-2 {
    margin-bottom: 8px;
}

.print-format-wrapper .mb-3 {
    margin-bottom: 16px;
}

.print-format-wrapper .mt-2 {
    margin-top: 8px;
}

/* --- 通用表格基础样式（不设置具体 padding，由各模板自行定义） --- */
/* 注意：移除了具体的 padding 设置，避免影响各模板的自定义样式 */
table.info-table,
table.items-table,
table.totals-table,
.print-format-wrapper .info-table,
.print-format-wrapper .items-table,
.print-format-wrapper .totals-table {
    border-collapse: collapse;
    width: 100%;
    font-size: 12px;
    margin-top: 10px;
    margin-bottom: 10px;
}

/* 只设置边框，不设置 padding */
table.info-table td,
table.items-table td,
table.totals-table td,
.print-format-wrapper .info-table td,
.print-format-wrapper .items-table td,
.print-format-wrapper .totals-table td {
    border: 1px solid #000;
}

/* 支持不同的边框颜色 */
.print-format-wrapper .info-table,
.print-format-wrapper .items-table,
.print-format-wrapper .totals-table {
    border: 1px solid #333;
}

.print-format-wrapper .info-table td,
.print-format-wrapper .items-table td,
.print-format-wrapper .totals-table td {
    border: 1px solid #333;
}

/* 隔行变色 - 通用样式 */
table.items-table tbody tr:nth-child(even),
.print-format-wrapper .items-table tbody tr:nth-child(even) {
    background-color: #f2f2f2 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* 支持不同的隔行背景色 */
.print-format-wrapper .items-table tbody tr:nth-child(even) {
    background-color: #f9f9f9 !important;
}

/* 表头样式 - 通用背景色 */
thead.table-header,
.print-format-wrapper .items-table thead {
    background-color: #e0e0e0 !important;
    font-weight: bold;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* 支持不同的表头背景色 */
.print-format-wrapper .items-table thead {
    background-color: #f5f5f5 !important;
}

.print-format-wrapper .items-table th {
    font-weight: 600;
    color: #171717;
    padding: 4px;
    text-align: center;
    border: 1px solid #333;
    background-color: #f5f5f5;
    vertical-align: middle;
}

.print-format-wrapper .items-table td {
    padding: 4px;
    border: 1px solid #333;
    vertical-align: middle;
    line-height: 1.15;
}

.print-format-wrapper .items-table tbody tr {
    background-color: #fff;
}

/* 通用表格打印颜色调整 */
.print-format-wrapper .items-table,
.print-format-wrapper .info-table,
.print-format-wrapper .totals-table {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* --- 文本对齐工具类 --- */
.text-center,
.print-format-wrapper .text-center {
    text-align: center;
}

.text-left,
.print-format-wrapper .text-left {
    text-align: left;
}

.text-right,
.print-format-wrapper .text-right {
    text-align: right;
}

.text-bold,
.print-format-wrapper .text-bold {
    font-weight: bold;
}

/* 支持不同的字重 */
.print-format-wrapper .text-bold {
    font-weight: 600;
}

/* --- 自定义标签样式 --- */
.custom-label {
    font-weight: bold;
    margin-right: 5px;
    display: inline-block;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    color: #000 !important;
}

/* --- 次要文本样式 --- */
.secondary-text,
.print-format-wrapper .secondary-text {
    font-size: 11px;
    color: #333;
    line-height: 1.2;
}

/* 支持不同的次要文本颜色 */
.print-format-wrapper .secondary-text {
    color: #666;
    line-height: 1.3;
}

/* --- 水印样式（基础样式，具体定位由各模板定义） --- */
.watermark {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
    margin: 0;
    padding: 0;
}

.watermark h4 {
    border: 2px solid rgba(204, 204, 204, 1);
    color: rgba(204, 204, 204, 1);
    padding: 10px 20px;
    transform: rotate(-15deg);
    -webkit-transform: rotate(-15deg);
    position: absolute;
    top: 15%;
    left: 35%;
    margin: 0;
    opacity: 0.3;
    font-size: 72px;
}

/* --- 签名区域样式（基础样式，具体 padding 由各模板定义） --- */
.signature-area,
.print-format-wrapper .signature-table {
    margin-top: 20px;
    width: 100%;
    font-size: 12px;
}

.signature-area td,
.print-format-wrapper .signature-table td {
    border: none;
}

.signature-line,
.print-format-wrapper .signature-line {
    border-top: 1px solid #000;
    width: 90%;
    margin-top: 30px;
}

/* 支持不同的签名线样式 */
.print-format-wrapper .signature-line {
    border-top: 1px solid #000;
    margin-top: 8px;
    height: 1px;
}

.print-format-wrapper .signature-table {
    border-collapse: collapse;
}

.print-format-wrapper .signature-cell {
    text-align: left;
    min-height: 80px;
    height: 80px;
}

.print-format-wrapper .signature-label {
    font-weight: 600;
    color: #171717;
    margin-bottom: 4px;
}

.print-format-wrapper .signature-name {
    font-weight: 600;
    color: #171717;
}

/* --- 复选框样式 --- */
.check-box-outline,
.print-format-wrapper .check-box-outline {
    width: 12px;
    height: 12px;
    border: 1px solid #000;
    display: inline-block;
    background-color: #fff;
    margin-top: 2px;
}

/* 支持不同尺寸的复选框 */
.print-format-wrapper .check-box-outline {
    width: 14px;
    height: 14px;
    border: 1px solid #333;
    margin: 0 auto;
}

/* --- 打印适配 (解决图片被强制拉伸) --- */
body:last-child .print-format td img {
    width: auto !important; /* 强制覆盖您提供的 100% 规则 */
    max-width: 100%;
}

/** 修复溢出导出多余空白页问题 */
#screenity-ui {
    overflow: hidden;
    display: none !important;
}

/* 下划线样式 */
.print-format u {
    text-decoration: underline;
    text-underline-offset: 0.2em;
    text-decoration-thickness: 1px;
}

/** Quill 编辑器样式 */
.print-format .ql-editor {
    color: rgb(0, 0, 0);
    line-height: 1.85;
}

.print-format .ql-editor h5 {
    margin-top: 1em;
}

.print-format .ql-editor li[data-list=checked]>.ql-ui,
.print-format .ql-editor li[data-list=unchecked]>.ql-ui {
    scale: 1.5;
}

.print-format .ql-editor li[data-list=unchecked] {
    display: none;
}

/* ============================================
   PDF 打印优化样式 (Print Optimization Styles)
   解决 PDF 渲染时的页头空间压缩问题
   ============================================ */

/* PDF 渲染时的页面断点优化 */
@media print {
    /* 1. 首页：无边距或最小边距 */
    @page :first {
        margin-top: 0mm !important;
        /* 你甚至可以在这里定义页眉页脚的内容区域 */
        @bottom-center {
            font-size: 12px;
            content: "" counter(page) " / " counter(pages);
        }
    }

    /* 2. 尾页：无边距或最小边距 */
    @page :last {
        margin-bottom: 0mm !important;
        @bottom-center {
            font-size: 12px;
            content: "" counter(page) " / " counter(pages);
        }
    }

    /* 3. 中间页：应用边距样式（仅中间页有效） */
    @page {
        @bottom-center {
            font-size: 12px;
            content: "" counter(page) " / " counter(pages);
        }
    }

    /* Body 重置 - 确保 PDF 渲染时没有多余的 margin 和 padding */
    body {
        margin-bottom: 0mm !important;
        padding: 0 5mm !important;
    }

    /* 打印标题样式优化 - 确保不占用额外空间 */
    .print-heading {
        margin-top: 0px !important;
        margin-bottom: 0px !important;
        padding-bottom: 0px !important;
    }

    .letter-head {
        margin-top: 5mm !important; /* PDF 渲染时为页头留出顶部空间 */
    }

    /* 页脚样式优化 */
    .letter-head-footer {
        margin-top: 0px !important;
    }

    .page-break {
        page-break-after: always;
    }
    
    .page-break:last-child {
        page-break-after: auto;
    }
    
    /* 确保页头在每页顶部正确显示 */
    #header-html {
        position: running(header);
    }
    
    /* 优化表格在 PDF 中的显示 */
    table {
        page-break-inside: auto;
    }
    
    tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }
    
    thead {
        display: table-header-group;
    }
    
    tfoot {
        display: table-footer-group;
    }
    
    /* 通用打印格式包装器优化 */
    .print-format-wrapper {
        page-break-inside: avoid;
    }
    
    .print-format-wrapper .items-table {
        page-break-inside: auto;
    }
    
    .print-format-wrapper .items-table tbody tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }
    
    .print-format-wrapper .items-table thead {
        display: table-header-group;
    }
    
    .print-format-wrapper .signature-table {
        page-break-inside: avoid;
    }
}
